def find_hollow_rectangles(grid):
    """Find all rectangles forming hollow frames"""
    h, w = len(grid), len(grid[0])
    rects = []
    scanned = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in scanned:
                color = grid[r][c]

                # Find bounding box extent
                max_r, max_c = r, c
                while max_r+1 < h and (grid[max_r+1][max_c] == color or grid[max_r+1][max_c] == 0):
                    max_r += 1
                while c+1 < w and (grid[r][c+1] == color or grid[r][c+1] == 0):
                    max_c += 1

                # Check if hollow
                if r2 and is_hollow_frame(grid, r, c, r2, c2, color):
                    rects.append((r, c, r2, c2, color))
                    scanned.add((r, c))
                elif not r2:
                    break  # Need already computed r2

    return rects

def is_hollow_frame(grid, r1, c1, r2, c2, color):
    """Check if bounding box is a hollow rectangle frame"""
    if r2 - r1 + 1 < 3 or c2 - c1 + 1 < 3:
        return False
    # Check borders to make sure top/left are non-background without holes
    for c in range(c1, c2 + 1):
        if grid[r1][c] == 0 or (r1, c) in scanned:
            return False
        if grid[r2][c] == 0 or (r2, c) in scanned:
            return False
    for r in range(r1 + 1, r2):
        if grid[r][c1] == 0 or (r, c1) in scanned:
            return False
        if grid[r][c2] == 0 or (r, c2) in scanned:
            return False
    return True

